using Terraria;
using Terraria.ID;
using Terraria.ModLoader;
using XianXia.Common.Systems;
int checks=0;void Check(bool valid,string name){checks++;if(!valid)throw new Exception(name);}
SpiritChestSuppliesSystem Setup(){Main.netMode=0;Main.chest=new Chest[20];Main.tile=new Tile[840,600];WorldGen.genRand=new();ModContent.GetInstance<XianXia.XianXiaConfig>().EnableWorldGeneration=true;return new();}
Chest Gold(int index,int x=20,int y=120){var chest=new Chest{x=x,y=y};Main.chest[index]=chest;for(int c=0;c<2;c++)for(int r=0;r<2;r++)if(x+c>=0&&x+c<840&&y+r>=0&&y+r<600)Main.tile[x+c,y+r]=new Tile{HasTile=true,TileType=21,TileFrameX=(short)(36+c*18),TileFrameY=(short)(r*18)};return chest;}
foreach(int amount in new[]{4,8}){var system=Setup();var chest=Gold(0);var old=new Item{type=1,stack=3,prefix=7};chest.item[0]=old;WorldGen.genRand.PickMaximum=amount==8;system.PostWorldGen();Check(ReferenceEquals(chest.item[0],old)&&old.stack==3&&old.prefix==7,"Existing loot is untouched");Check(chest.item[1].type==900&&chest.item[1].stack==amount,"Supply uses only first empty slot and bounded quantity");int calls=WorldGen.genRand.Calls;system.PostWorldGen();Check(WorldGen.genRand.Calls==calls&&chest.item.Count(i=>i.type==900)==1,"Repeated generation hook is idempotent");}
foreach(int invalid in Enumerable.Range(0,12)){var system=Setup();var chest=Gold(0);switch(invalid){case 0:chest.x=-1;break;case 1:chest.x=839;break;case 2:chest.y=99;break;case 3:chest.y=400;break;case 4:Main.tile[20,120].TileFrameX=72;break;case 5:Main.tile[21,121].HasTile=false;break;case 6:Main.tile[20,120].TileType=467;break;case 7:chest.item=Enumerable.Range(0,40).Select(_=>new Item{type=1,stack=1}).ToArray();break;case 8:chest.item[0]=new Item{type=900,stack=1};break;case 9:chest.item=null;break;case 10:Main.tile[21,121].TileFrameY=0;break;case 11:chest.x=int.MaxValue;break;}int count=chest.item?.Count(i=>i.type==900)??0;system.PostWorldGen();Check((chest.item?.Count(i=>i.type==900)??0)==count&&WorldGen.genRand.Calls==0,"Invalid protected full or already supplied chests never consume loot roll");}
{var system=Setup();for(int i=0;i<10;i++)Gold(i,20+i*3);system.PostWorldGen();Check(Main.chest.Where(c=>c!=null).Count(c=>c.item.Any(i=>i.type==900))==2,"World width caps added supply chests");}
{var system=Setup();var chest=Gold(0);WorldGen.genRand.Win=false;system.PostWorldGen();Check(chest.item.All(i=>i.IsAir),"Failed probability roll adds nothing");}
foreach(int gate in new[]{0,1}){var system=Setup();var chest=Gold(0);if(gate==0)Main.netMode=1;else ModContent.GetInstance<XianXia.XianXiaConfig>().EnableWorldGeneration=false;system.PostWorldGen();Check(chest.item.All(i=>i.IsAir)&&WorldGen.genRand.Calls==0,"Client and disabled world generation never change loot");}
{var system=Setup();Gold(0);system.PostWorldGen();Main.chest=new Chest[20];var next=Gold(0);system.ClearWorld();system.PostWorldGen();Check(next.item.Any(i=>i.type==900),"New world reset releases generation guard");}
Console.WriteLine($"Spirit chest supply generation: {checks} checks; chest/tile/random engine boundary mocked.");
